INSERT INTO site_content (`id`,`type`,`title`,`title_en`,`title_zh`,`category`,`category_en`,`category_zh`,`industry`,`summary`,`summary_en`,`summary_zh`,`image`,`status`,`date`,`content`,`content_en`,`content_zh`,`features_en`,`features_zh`,`specifications_en`,`specifications_zh`,`show_on_home`,`home_order`,`industry_ids`) SELECT 'grab-ship-unloader','products','Grab ship unloader','Grab ship unloader','抓斗卸船机','Ports','Ports','港口','ports','Custom-engineered equipment for large-scale bulk cargo unloading.','Custom-engineered equipment for large-scale bulk cargo unloading.','面向大规模港口散货卸载的工程装备，可根据现场需求定制。','/assets/tzme-j/products/grab-unloader.jpg','published',NULL,'Structural fabrication, assembly, commissioning and complete-unit delivery for demanding port applications.','Structural fabrication, assembly, commissioning and complete-unit delivery for demanding port applications.','由主体承载结构、行走机构、门架、臂架和机械平台等组成，可提供结构制作、装配调试及整机交付。','Load-bearing structures and machinery platform
Electrical system integration
Factory assembly, commissioning and testing
Complete-unit delivery','主体承载结构与机械平台
电气控制系统安装
出厂前装配、调试与测试
整机运输与项目交付','Reference: Turkey grab ship unloader
Capacity: 2,000 t/h (reference project)
Delivery: Complete-unit shipment
Configuration: Engineered to project requirements','案例参考：土耳其抓斗卸船机
处理能力：2,000 t/h（项目案例）
交付方式：整机发运
配置：根据项目需求定制',0,0,'ports' WHERE NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-15-j-design-v1') AND NOT EXISTS (SELECT 1 FROM site_content WHERE id='grab-ship-unloader');
INSERT INTO site_content (`id`,`type`,`title`,`title_en`,`title_zh`,`category`,`category_en`,`category_zh`,`industry`,`summary`,`summary_en`,`summary_zh`,`image`,`status`,`date`,`content`,`content_en`,`content_zh`,`features_en`,`features_zh`,`specifications_en`,`specifications_zh`,`show_on_home`,`home_order`,`industry_ids`) SELECT 'pipe-rack','products','Modular pipe racks','Modular pipe racks','模块化管廊','Energy infrastructure','Energy infrastructure','能源基础设施','energy','Custom structural fabrication and assembly tailored to project conditions and technical requirements.','Custom structural fabrication and assembly tailored to project conditions and technical requirements.','用于集中敷设电力、通信、给排水等多种管线的综合通道设施，广泛应用于城市基础设施建设。公司生产的管廊采用预制模块化设计，具有施工速度快、使用寿命长、维护方便等特点，能够有效提升城市地下空间的利用效率。','/assets/tzme-j/products/pipe-rack.jpg','published',NULL,'Engineering and manufacturing shaped around the project’s structure, assembly and delivery requirements.','Engineering and manufacturing shaped around the project’s structure, assembly and delivery requirements.','用于集中敷设电力、通信、给排水等多种管线的综合通道设施，广泛应用于城市基础设施建设。公司生产的管廊采用预制模块化设计，具有施工速度快、使用寿命长、维护方便等特点，能够有效提升城市地下空间的利用效率。','Custom structural fabrication
Factory assembly and quality control
Delivery aligned with project requirements','预制模块化：采用预制模块化设计，便于快速施工和安装。
耐久性强：使用高性能混凝土和防腐材料，确保长期稳定运行。
空间优化：合理布局管线，最大化利用地下空间，减少重复施工。
智能化管理：配备智能监测系统，实时监控管廊运行状态，提升管理效率。','Application: Energy infrastructure
Scope: Engineering, fabrication and assembly
Configuration: Project-specific','应用：能源基础设施
服务范围：设计、制造与装配
配置：根据项目要求定制',0,0,'energy' WHERE NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-15-j-design-v1') AND NOT EXISTS (SELECT 1 FROM site_content WHERE id='pipe-rack');
INSERT INTO site_content (`id`,`type`,`title`,`title_en`,`title_zh`,`category`,`category_en`,`category_zh`,`industry`,`summary`,`summary_en`,`summary_zh`,`image`,`status`,`date`,`content`,`content_en`,`content_zh`,`features_en`,`features_zh`,`specifications_en`,`specifications_zh`,`show_on_home`,`home_order`,`industry_ids`) SELECT 'rotor-sail','products','Rotor sails','Rotor sails','旋筒帆','Marine engineering','Marine engineering','海洋工程','energy','Custom structural fabrication and assembly tailored to project conditions and technical requirements.','Custom structural fabrication and assembly tailored to project conditions and technical requirements.','结合项目工况与技术要求，提供定制化的结构制造与装配交付。','/assets/tzme-j/products/rotor-sail.jpg','published',NULL,'Engineering and manufacturing shaped around the project’s structure, assembly and delivery requirements.','Engineering and manufacturing shaped around the project’s structure, assembly and delivery requirements.','围绕客户项目的结构、装配与交付需求，开展工程设计与制造。','Custom structural fabrication
Factory assembly and quality control
Delivery aligned with project requirements','定制化结构制造
工厂装配与质量控制
根据项目需求交付','Application: Marine engineering
Scope: Engineering, fabrication and assembly
Configuration: Project-specific','应用：海洋工程
服务范围：设计、制造与装配
配置：根据项目要求定制',0,0,'energy' WHERE NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-15-j-design-v1') AND NOT EXISTS (SELECT 1 FROM site_content WHERE id='rotor-sail');
INSERT INTO site_content (`id`,`type`,`title`,`title_en`,`title_zh`,`category`,`category_en`,`category_zh`,`industry`,`summary`,`summary_en`,`summary_zh`,`image`,`status`,`date`,`content`,`content_en`,`content_zh`,`features_en`,`features_zh`,`specifications_en`,`specifications_zh`,`show_on_home`,`home_order`,`industry_ids`) SELECT 'canada-energy','articles','Bridging continents, building energy futures','Bridging continents, building energy futures','跨越洲际，连接能源未来：重钢机械助力中加工程合作','Company news','Company news','公司新闻','','Modular fabrication and system integration for Canadian energy and port infrastructure.','Modular fabrication and system integration for Canadian energy and port infrastructure.','以模块化预制、制造与系统集成能力，服务加拿大能源与港口基础设施建设。','/assets/tzme-j/news/canada-energy.jpg','published',NULL,'<h2>Connecting energy and engineering</h2><p>TZME participates in Canadian energy and port infrastructure through large-scale fabrication and modular prefabrication.</p><h2>Modular manufacturing</h2><p>For the REEF project, TZME manufactures pipeline-gallery modules, moving complex site work into controlled factory fabrication and integration.</p><h2>From factory to project site</h2><p>Full-process quality control, technical alignment and integrated execution support demanding international projects.</p>','<h2>Connecting energy and engineering</h2><p>TZME participates in Canadian energy and port infrastructure through large-scale fabrication and modular prefabrication.</p><h2>Modular manufacturing</h2><p>For the REEF project, TZME manufactures pipeline-gallery modules, moving complex site work into controlled factory fabrication and integration.</p><h2>From factory to project site</h2><p>Full-process quality control, technical alignment and integrated execution support demanding international projects.</p>','<h2>连接能源与工程需求</h2><p>重钢机械以大型装备制造和模块化预制能力，参与加拿大能源及港口基础设施项目。</p><h2>模块化制造与项目执行</h2><p>在 REEF 项目中，公司承担大型管廊模块的制造，将复杂的现场建设环节转化为可控的工厂预制与集成作业。</p><p>通过全过程质量控制、客户技术标准对齐与机电系统集成，支撑复杂国际工程的协同执行。</p><h2>从制造基地到项目现场</h2><p>制造基地的模块预制、装配和发运，连接客户的现场工程需求与中国制造能力。</p>',NULL,NULL,NULL,NULL,0,0,'' WHERE NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-15-j-design-v1') AND NOT EXISTS (SELECT 1 FROM site_content WHERE id='canada-energy');
INSERT INTO site_content (`id`,`type`,`title`,`title_en`,`title_zh`,`category`,`category_en`,`category_zh`,`industry`,`summary`,`summary_en`,`summary_zh`,`image`,`status`,`date`,`content`,`content_en`,`content_zh`,`features_en`,`features_zh`,`specifications_en`,`specifications_zh`,`show_on_home`,`home_order`,`industry_ids`) SELECT 'annual-gala','articles','TZME’s 2026 themed annual conference','TZME’s 2026 themed annual conference','重钢机械 2026 主题年会圆满举行','Company news','Company news','公司新闻','','Reflecting on the journey and bringing teams together for the next chapter.','Reflecting on the journey and bringing teams together for the next chapter.','回顾发展历程，凝聚团队力量，共同开启新的工程与制造篇章。','/assets/tzme-j/news/annual-gala.jpg','published',NULL,'<h2>Teams together for a new chapter</h2><p>On February 3, TZME held its themed annual conference with employees and representatives from clients and partner organisations.</p><h2>Collaboration and shared growth</h2><p>Departments presented performances, and suppliers and partners were recognised for their contributions during the past year.</p><h2>Engineering and manufacturing ahead</h2><p>TZME continues to serve custom equipment projects through dedicated teams, manufacturing capability and collaboration.</p>','<h2>Teams together for a new chapter</h2><p>On February 3, TZME held its themed annual conference with employees and representatives from clients and partner organisations.</p><h2>Collaboration and shared growth</h2><p>Departments presented performances, and suppliers and partners were recognised for their contributions during the past year.</p><h2>Engineering and manufacturing ahead</h2><p>TZME continues to serve custom equipment projects through dedicated teams, manufacturing capability and collaboration.</p>','<h2>凝聚团队，共启新篇</h2><p>公司于 2 月 3 日举办主题年会，公司领导、员工及客户与合作伙伴代表共同回顾过往、展望未来。</p><h2>协作与共同成长</h2><p>年会呈现了各部门准备的节目，并对过去一年作出贡献的供应商与合作伙伴进行表彰。</p><h2>以制造与工程继续前行</h2><p>公司将继续围绕非标机械装备定制业务，以专业团队、制造能力与协作精神服务客户项目。</p>',NULL,NULL,NULL,NULL,0,0,'' WHERE NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-15-j-design-v1') AND NOT EXISTS (SELECT 1 FROM site_content WHERE id='annual-gala');
INSERT INTO projects (`id`,`title_en`,`title_zh`,`industry_en`,`industry_zh`,`location_en`,`location_zh`,`image_alt_en`,`image_alt_zh`,`summary_en`,`summary_zh`,`content_en`,`content_zh`,`capacity_label_en`,`capacity_label_zh`,`capacity_en`,`capacity_zh`,`technology_label_en`,`technology_label_zh`,`technology_en`,`technology_zh`,`scope_label_en`,`scope_label_zh`,`scope_en`,`scope_zh`,`image`,`status`,`sort_order`,`show_on_home`,`home_order`) SELECT 'turkey-grab-unloader','Grab ship unloader for Turkey','土耳其抓斗卸船机','Ports & terminals','港口与码头','Turkey','土耳其','Grab ship unloader for Turkey','土耳其抓斗卸船机','Large-scale grab ship unloader fabrication, assembly, commissioning and complete-unit delivery for Turkey.','面向土耳其港口散货卸载需求，完成大型抓斗卸船机的结构制作、装配调试与整机交付。','<h2>Project overview</h2><p>Manufacturing and installation of a grab-type ship unloader for Turkey, with a handling capacity of up to 2,000 tons per hour.</p><h2>Equipment and manufacturing scope</h2><p>Each unloader weighs approximately 2,050 tonnes, comprising 1,400 tonnes of structural fabrication and 650 tonnes of electrical installation. Overall dimensions are approximately 96.4 m × 31.5 m × 61.5 m.</p><h2>Assembly and complete-unit delivery</h2><p>Assembly, commissioning and performance tests take place before shipment, reducing the work required at the destination.</p>','<h2>项目概况</h2><p>本项目为抓斗式卸船机的制作和安装，设备最终使用地点土耳其伊斯德米尔•奥亚克港，当地环境温度+0 °C / +45 °C，</p><p>该抓斗卸船机的工作能力突出，每小时工作能力可达2000吨，能充分满足港口大规模、高效率的散货卸载需求，有效提升港口货物周转效率，减少船舶滞港时间，为港口运营提供强有力的设备支撑。</p><h2>设备与制造范围</h2><p>每台卸船机总重量约 2,050 吨。结构制作部分约 1,400 吨，电气安装部分约 650 吨。</p><p>设备长度约 96.4 米，宽度约 31.5 米，高度约 61.5 米。</p><h2>装配与整机交付</h2><p>本项目的交货条件明确为整机发货，这意味着设备在出厂前需完成所有部组的组装、调试以及性能测试，确保设备整体性能达标后，以完整的整机形式运输至土耳其伊斯德米尔・奥亚克港。这种交货方式可大幅减少设备在港口现场的组装工作量，缩短安装周期，降低现场安装风险，确保设备能够快速投入港口作业。</p>','Handling capacity','处理能力','2,000 t/h','2,000 t/h','Technology','技术方案','Grab ship unloader','抓斗卸船机','Delivery','交付方式','Complete-unit shipment','整机发运','/assets/tzme-j/projects/turkey-unloader-01.jpg','published',0,0,0 WHERE NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-15-j-design-v1') AND NOT EXISTS (SELECT 1 FROM projects WHERE id='turkey-grab-unloader');
