UPDATE site_settings SET configuration=JSON_SET(configuration,'$."about"."description"."zh"','公司是一家主要面向国际市场的非标机械装备定制服务商，主要产品有港口机械、矿山机械、造桥机械、旅游观光设施及其他大型连续搬运装备、起重机械、冶金设备、压力容器、环保设备和特种船舶等，年综合生产能力达4.5万吨以上。公司保有一批国际知名的高端客户，产品出口到美国、德国、澳大利亚、巴西、日本、南非、加拿大、丹麦、韩国等六十多个国家和地区。') WHERE id='about-tzme' AND JSON_UNQUOTE(JSON_EXTRACT(configuration,'$."about"."description"."zh"')) <=> '天津重型钢结构机械设备有限公司设计、制造并交付按需定制的重型钢结构装备。从客户的工况要求或图纸开始，到设备在现场完成调试，设计、焊接、机加工、试装、出口包装和安装监督均由我们自主完成。' AND NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-15-j-design-v1');
UPDATE site_settings SET configuration=JSON_SET(configuration,'$."about"."description"."en"','Established in 2002, TZME provides custom-built, non-standard machinery and equipment for international markets. Six production bases support engineering, fabrication, assembly and project delivery.') WHERE id='about-tzme' AND JSON_UNQUOTE(JSON_EXTRACT(configuration,'$."about"."description"."en"')) <=> 'Tianjin Heavy Steel Machinery Equipment Co., Ltd. designs, fabricates and delivers engineered-to-order heavy steel equipment. Our work starts from a client''s duty statement or drawing set and ends with a commissioned machine on site — design, welding, machining, trial assembly, export packing and erection supervision are all handled in-house.' AND NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-15-j-design-v1');
UPDATE site_settings SET configuration=JSON_SET(configuration,'$."about"."description2"."zh"','制造基地总占地面积约45万平方米，格林兰基地拥有225米海岸线，衔接大型设备装配与装船运输。') WHERE id='about-tzme' AND JSON_UNQUOTE(JSON_EXTRACT(configuration,'$."about"."description2"."zh"')) <=> '约 90% 的产品出口，主要服务于澳大利亚、欧洲和北美的矿业企业、港口运营商及 EPC 承包商。' AND NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-15-j-design-v1');
UPDATE site_settings SET configuration=JSON_SET(configuration,'$."about"."description2"."en"','The manufacturing bases cover approximately 450,000 m². The Greenland base has a 225-metre coastline supporting large equipment assembly and shipment.') WHERE id='about-tzme' AND JSON_UNQUOTE(JSON_EXTRACT(configuration,'$."about"."description2"."en"')) <=> 'Roughly 90 % of our output is exported, mainly to mining houses, port operators and EPC contractors in Australia, Europe and North America.' AND NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-15-j-design-v1');
